import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent;O=R/'results';s=pd.read_csv(O/'summary.csv');delta=pd.read_csv(O/'deltas.csv');c=pd.read_csv(O/'model_choices.csv')
